def handle_user_initials(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    words = user["name"].split()
    initials = "".join(word[0].upper() for word in (words[:1] + words[-1:]))
    return 200, {"initials": initials}

